awk '
/\/api\/v[0-9]+\/internal\// {
  if ($1 !~ /^10\./) {
    # Extract timestamp
    match($0, /\[([^\]]+)\]/, ts);
    timestamp = ts[1];

    # Parse: 23/Aug/2024:03:38:50 +0000
    split(timestamp, parts, /[:\/]/);
    day = parts[1];
    month = parts[2];
    year = parts[3];
    time = parts[4] ":" parts[5] ":" parts[6];

    # Convert month name to number
    months["Jan"]="01"; months["Feb"]="02"; months["Mar"]="03";
    months["Apr"]="04"; months["May"]="05"; months["Jun"]="06";
    months["Jul"]="07"; months["Aug"]="08"; months["Sep"]="09";
    months["Oct"]="10"; months["Nov"]="11"; months["Dec"]="12";

    iso_timestamp = year "-" months[month] "-" day "T" time;

    # Replace timestamp in the line
    sub(/\[[^\]]+\]/, iso_timestamp);
    print;
  }
}' /var/log/app/access.log > /home/user/internal_hits.log

